import type { HistoricalStory } from '../types'

export const historicalStories: HistoricalStory[] = [
  {
    id: 'rome', title: 'Rome: republic, empire, and afterlife', subtitle: 'How a city-state conquered the Mediterranean—and why Rome continued after 476', category: 'Empires & states', period: '509 BCE–1453 CE', estimatedMinutes: 11, featured: true, color: '#c74e47',
    introduction: 'Rome was not born an empire, and it did not simply vanish when the western imperial court ended. This story follows the bargains, wars, inequalities, institutions, and religious changes that repeatedly remade Roman power across almost two millennia.',
    conclusion: 'Roman rule changed from a competitive republic into a monarchy, split between several courts, and survived in Constantinople for nearly another thousand years after the western office ended. Its law, languages, cities, religions, and arguments about citizenship outlived every Roman government.',
    steps: [
      { year: -509, section: 'I · A city becomes a state', title: 'Romans replace kings with a republic', description: 'Roman tradition dated the expulsion of the kings to 509 BCE, though the early Republic emerged through a less tidy process. Magistrates, assemblies, and a Senate dominated by elite families divided authority while citizens contested status and obligation.', significance: 'The republic was neither fully democratic nor fixed at birth; its institutions developed through social conflict and expansion.', entity: 'Roman Republic', pointId: 'rome-city', dateLabel: 'Traditionally 509 BCE' },
      { year: -264, section: 'II · The Mediterranean struggle', title: 'War with Carthage changes the scale', description: 'The First Punic War drew Rome and Carthage into a long contest over Sicily and the western Mediterranean. Rome built fleets, absorbed terrible losses, and emerged with its first overseas provinces.', significance: 'Victory pushed a land-based Italian power toward permanent naval, provincial, and imperial commitments.', entity: 'Carthage', pointId: 'carthage-city', dateLabel: '264 BCE' },
      { year: -218, section: 'II · The Mediterranean struggle', title: 'Hannibal brings war into Italy', description: 'Hannibal crossed the Alps and destroyed several Roman armies, but Rome refused negotiated defeat. Its alliance system, manpower, and campaigns in Iberia and North Africa eventually reversed the war.', significance: 'Survival demonstrated the resilience—and the human cost—of Rome’s Italian alliance network.', entity: 'Carthaginian Empire', pointId: 'carthage-city', dateLabel: '218 BCE' },
      { year: -146, section: 'III · Victory destabilizes the Republic', title: 'Conquest brings wealth and upheaval', description: 'By 146 BCE Roman armies had destroyed Carthage and defeated major Greek rivals. Enslaved captives, tribute, land, and command opportunities enriched elites while service and dispossession sharpened tensions at home.', significance: 'Mediterranean dominance magnified inequalities the republican constitution struggled to contain.', entity: 'Roman Republic', pointId: 'rome-city', dateLabel: '146 BCE' },
      { year: -44, section: 'III · Victory destabilizes the Republic', title: 'Caesar is killed, but the old order does not return', description: 'Julius Caesar’s accumulation of offices followed decades of political violence and civil war. Senators assassinated him in the name of liberty, yet their act opened another round of war rather than restoring stable republican competition.', significance: 'Removing one ruler could not resolve the military loyalties, rival ambitions, and inequalities beneath the crisis.', entity: 'Roman Republic', eventId: 'caesar' },
      { year: -27, section: 'IV · Monarchy behind republican forms', title: 'Augustus builds the Principate', description: 'Octavian, the final victor of the civil wars, accepted the name Augustus and arranged powers that placed armies, provinces, and patronage under his control. Republican offices continued, but no peer could safely rival him.', significance: 'The settlement made one-man rule durable by presenting it as restoration rather than revolution.', entity: 'Roman Empire', pointId: 'rome-city', dateLabel: '27 BCE' },
      { year: 100, section: 'V · An interconnected imperial world', title: 'Cities, roads, taxes, and armies bind the provinces', description: 'At its height the empire governed many languages, religions, and local legal traditions around the Mediterranean. Provincial elites, soldiers, merchants, migrants, and enslaved people moved through a network centered on cities and sustained by taxation and force.', significance: 'Roman integration was real but uneven: participation, coercion, and local autonomy existed together.', entity: 'Roman Empire' },
      { year: 200, section: 'V · An interconnected imperial world', title: 'Roman citizenship widens', description: 'Military service, local status, and imperial grants had already spread citizenship far beyond Italy. In 212 Emperor Caracalla extended it to nearly all free inhabitants, changing the legal meaning of belonging to the empire.', significance: '“Roman” had become a political status shared across provinces, not an identity confined to one city or people.', entity: 'Roman Empire', dateLabel: 'Early 3rd century' },
      { year: 300, section: 'VI · Crisis and reconstruction', title: 'The empire is governed from several centers', description: 'Third-century invasions, civil wars, epidemics, and rapid changes of emperor strained the state. Diocletian and his colleagues rebuilt taxation and the army, then divided imperial responsibility among several rulers and courts.', significance: 'Survival required a more centralized state and acknowledged that Rome could no longer be ruled effectively from Rome alone.', entity: 'Roman Empire', pointId: 'rome-city' },
      { year: 313, section: 'VII · A Christian imperial order', title: 'Christian worship gains imperial toleration', description: 'Constantine and Licinius agreed to restore confiscated property and permit Christian worship. Imperial favor then helped Christian institutions grow, even as older religious practices persisted and theological disputes intensified.', significance: 'A persecuted movement became increasingly entangled with imperial authority and public life.', entity: 'Roman Empire', eventId: 'milan' },
      { year: 330, section: 'VII · A Christian imperial order', title: 'Constantinople becomes a New Rome', description: 'Constantine dedicated an expanded capital at Byzantium on the Bosporus. Its defensible position and access to Black Sea and Mediterranean routes made it a durable center of court, administration, and commerce.', significance: 'The political center shifted east without its inhabitants ceasing to think of their state as Roman.', entity: 'Eastern Roman Empire', eventId: 'constantinople-founded' },
      { year: 400, section: 'VIII · Two courts, one Roman world', title: 'Eastern and western governments diverge', description: 'After Theodosius I died in 395, his sons ruled from eastern and western courts. Both governments were Roman, but their revenues, military pressures, and political stability increasingly differed.', significance: 'The division was an administrative response, not a moment when one civilization split cleanly in two.', entity: 'Western Roman Empire' },
      { year: 476, section: 'VIII · Two courts, one Roman world', title: 'The western imperial office ends', description: 'Odoacer removed Romulus Augustulus and ruled Italy without installing another western emperor. Roman institutions, communities, and successor kingdoms continued, while the emperor in Constantinople still claimed Roman authority.', significance: '476 is a useful convention, not the instant “fall” of Roman society or the end of the empire everywhere.', entity: 'Western Roman Empire', eventId: 'rome-476' },
      { year: 500, section: 'IX · Rome continues in the east', title: 'An eastern Roman recovery', description: 'From Constantinople, Justinian’s government codified centuries of Roman law and reconquered parts of North Africa and Italy. War, plague, and the enormous cost of defense limited how long many gains could be held.', significance: 'The eastern empire preserved Roman statehood while transforming it in a Greek-speaking, Christian Mediterranean.', entity: 'Eastern Roman Empire', pointId: 'constantinople-city' },
      { year: 1200, section: 'IX · Rome continues in the east', title: 'A smaller but resilient Byzantine state', description: 'Centuries of war, trade, diplomacy, and religious change had reshaped the empire. Crusader armies captured Constantinople in 1204 and fractured Byzantine authority before an imperial restoration in 1261.', significance: 'Roman inheritance survived through adaptation, but it was vulnerable to rivals from both eastern and western Christian worlds.', entity: 'Byzantine Empire', pointId: 'constantinople-city' },
      { year: 1453, section: 'X · Conquest and legacy', title: 'Constantinople becomes an Ottoman capital', description: 'Mehmed II’s forces captured Constantinople after a major siege, ending the Byzantine imperial state. The Ottoman court made the city a capital of another multiethnic empire rather than leaving it as a relic.', significance: 'Roman government ended, but Roman law, Orthodox Christianity, scholarship, architecture, and imperial memory continued.', eventId: 'constantinople', entity: 'Ottoman Empire' },
    ],
  },
  {
    id: 'silk-roads', title: 'Worlds of the Silk Roads', subtitle: 'The changing land and sea networks that carried goods, beliefs, technologies, and people', category: 'Exchange & movement', period: '518 BCE–1498 CE', estimatedMinutes: 7, featured: true, color: '#4fb3a5',
    introduction: 'There was never one continuous “Silk Road” from China to Rome. There were overlapping routes, ports, borderlands, and relay markets whose importance shifted with empires, environments, technologies, and the people who made each journey possible.',
    conclusion: 'No single empire created or controlled the Silk Roads. Their history belongs to merchants, sailors, pastoralists, pilgrims, translators, craftspeople, captives, and cities that connected journeys across many shorter stages. Oceanic routes did not replace exchange; they changed its geography and balance of power.',
    steps: [
      { year: -518, section: 'I · Roads before the name', title: 'Persian highways link an imperial world', description: 'Achaemenid rulers used roads, couriers, garrisons, and provincial centers to govern territory from the Aegean to Central and South Asia. These were imperial routes, not yet a transcontinental trade system called the Silk Roads.', significance: 'Later exchange grew through older regional networks rather than appearing all at once.', entity: 'Achaemenid Empire', eventId: 'persepolis' },
      { year: -138, section: 'II · Han expansion looks west', title: 'Zhang Qian’s missions widen imperial knowledge', description: 'The Han court sent Zhang Qian toward Central Asia in search of allies. His reports described powerful states, coveted horses, and markets beyond the frontier, encouraging diplomacy and military expansion into the Hexi Corridor.', significance: 'Political intelligence and frontier strategy helped expand the range of long-distance exchange.', entity: 'Han', eventId: 'zhang-qian' },
      { year: 100, section: 'II · Han expansion looks west', title: 'Goods travel farther than most people', description: 'Silk, glass, horses, spices, metals, and other goods passed through many hands between Han China, Central Asia, India, Iran, and the Roman world. Very few merchants crossed the entire distance.', significance: 'The network worked through chains of regional exchange, not a single caravan route between two endpoints.', entity: 'Han', routeId: 'silk-roads' },
      { year: 500, section: 'III · Religions and technologies move', title: 'Borderlands become places of translation', description: 'Buddhist communities, Christian groups, Zoroastrians, and others traveled or established institutions along Central Asian routes. Artistic forms, stories, languages, and technologies changed as communities adapted them to new settings.', significance: 'Exchange transformed ideas as well as transporting them; movement was never culturally one-way.', entity: 'Sasanian Empire', routeId: 'silk-roads' },
      { year: 762, section: 'IV · New centers in an Islamic world', title: 'Baghdad joins regional and global circuits', description: 'The Abbasid capital drew administrators, scholars, artisans, and commodities from a vast area. Translation and scholarship flourished through institutions and patronage connected to Greek, Persian, Indian, and other traditions.', significance: 'A new political center reorganized routes without erasing the local societies that sustained them.', entity: 'Abbasid Caliphate', eventId: 'baghdad-founded' },
      { year: 1000, section: 'V · Land routes meet maritime worlds', title: 'Song ports face the Indian Ocean', description: 'Commercial growth under the Song linked inland production to ports and overseas markets. Ceramics, textiles, aromatics, metals, and knowledge moved through Southeast Asian and Indian Ocean cities as well as overland corridors.', significance: 'The Silk Roads were maritime as well as terrestrial, and coastal cities were central rather than peripheral.', entity: 'Song Empire', routeId: 'indian-ocean' },
      { year: 1206, section: 'VI · The Mongol century', title: 'Conquest creates a connected but violent empire', description: 'Chinggis Khan united major steppe groups, and later campaigns destroyed cities and states across Eurasia. Mongol rulers also protected routes, moved specialists, and built relay systems across related khanates.', significance: 'Greater connectivity was inseparable from conquest, forced displacement, tribute, and mass death.', entity: 'Mongol Empire', eventId: 'chinggis-khan' },
      { year: 1279, section: 'VI · The Mongol century', title: 'Related khanates span Eurasia', description: 'Mongol-ruled states connected China, Central Asia, Iran, and the western steppe, though they were never politically uniform for long. Diplomats, merchants, clerics, envoys, and technologies crossed their borders.', significance: 'Shared dynastic origins could facilitate movement even as successor rulers pursued competing interests.', entity: 'Mongol Empire', routeId: 'silk-roads' },
      { year: 1405, section: 'VII · Oceans gain new prominence', title: 'Zheng He’s fleets cross the Indian Ocean', description: 'Ming expeditions visited Southeast Asian ports, South Asia, Arabia, and East Africa. They displayed imperial power and participated in diplomatic and commercial networks that long predated their arrival.', significance: 'The voyages reveal an ocean already dense with states, merchants, and navigational knowledge.', entity: 'Ming Chinese Empire', eventId: 'zheng-he' },
      { year: 1498, section: 'VII · Oceans gain new prominence', title: 'Portuguese fleets enter established networks', description: 'Vasco da Gama reached Calicut after rounding southern Africa. Portuguese forces then sought profit and strategic control through fortified ports and naval violence within an existing Indian Ocean commercial world.', significance: 'New armed competitors shifted routes and power; they did not “discover” an empty or disconnected ocean.', entity: 'Portugal', eventId: 'da-gama' },
    ],
  },
  {
    id: 'african-networks', title: 'African states and global networks', subtitle: 'Gold, scholarship, cities, farming, and ocean trade from the Sahel to the Swahili coast', category: 'Cities & networks', period: '300–1493 CE', estimatedMinutes: 7, featured: true, color: '#d2943d',
    introduction: 'Africa’s past cannot be reduced to the arrival of Europeans or to one model of “empire.” This story follows distinct states and commercial worlds that connected the Sahara, Niger basin, southern plateau, Red Sea, and Indian Ocean.',
    conclusion: 'African states drew power from many combinations of farming, cattle, minerals, river transport, religious authority, taxation, and long-distance exchange. Their cities were active centers of scholarship and production, while regional communities—not foreign visitors—built and sustained the networks shown here.',
    steps: [
      { year: 300, section: 'I · Red Sea and Sahelian worlds', title: 'Aksum connects highlands and sea routes', description: 'The kingdom of Aksum linked agricultural highlands in the Horn of Africa with Red Sea commerce. Its rulers issued coins, erected monumental stelae, and adopted Christianity during the fourth century.', significance: 'African states participated directly in Mediterranean, Arabian, and Indian Ocean worlds.', entity: 'Axum', source: { title: 'Encyclopaedia Britannica: Aksum', url: 'https://www.britannica.com/place/Aksum-ancient-kingdom-Africa' } },
      { year: 700, section: 'I · Red Sea and Sahelian worlds', title: 'Wagadu grows around exchange and authority', description: 'The state commonly called the Ghana Empire developed between the Senegal and Niger rivers. Rulers benefited from agricultural production and taxed commerce moving between gold-producing regions and Saharan markets.', significance: 'Trans-Saharan trade depended on Sahelian political power and local production, not only distant demand.', entity: 'Empire of Ghana', routeId: 'trans-saharan' },
      { year: 1000, section: 'II · Coasts and plateaus', title: 'Swahili ports face the Indian Ocean', description: 'African coastal towns linked inland goods and communities with merchants sailing monsoon routes. Swahili language and culture developed through local histories and centuries of interaction across the ocean.', significance: 'The coast was neither isolated nor merely an outpost of foreigners; it shaped its own cosmopolitan world.', routeId: 'indian-ocean', pointId: 'kilwa' },
      { year: 1100, section: 'II · Coasts and plateaus', title: 'Great Zimbabwe expands', description: 'A powerful state grew around cattle, farming, gold exchange, and a monumental stone-built center on the southern plateau. Its architecture was created by ancestors of Shona-speaking communities.', significance: 'The site demonstrates Indigenous urbanism and state formation connected to, but not caused by, ocean trade.', entity: 'Great Zimbabwe', eventId: 'great-zimbabwe' },
      { year: 1200, section: 'III · Mali and the Niger world', title: 'Mali rises after Ghana', description: 'Mali drew together fertile lands, gold-producing regions, river corridors, and caravan routes. Its rulers governed through layered relationships with towns, provinces, lineages, and military leaders rather than a uniform modern bureaucracy.', significance: 'Successor states adapted older networks while building new political coalitions.', entity: 'Mali', routeId: 'trans-saharan' },
      { year: 1324, section: 'III · Mali and the Niger world', title: 'Mansa Musa’s pilgrimage announces Mali’s wealth', description: 'Mansa Musa traveled to Mecca through Cairo with a large entourage and conspicuous quantities of gold. The journey joined devotion, diplomacy, reputation, and the logistics of ruling a far-reaching state.', significance: 'The famous display matters because it reveals Mali’s place within African and Islamic political worlds.', entity: 'Mali', eventId: 'mansa-musa' },
      { year: 1400, section: 'III · Mali and the Niger world', title: 'Timbuktu links commerce and scholarship', description: 'Timbuktu’s markets connected desert caravans with the Niger bend, while mosques, teachers, students, and manuscript collections made it an important center of learning. Its prominence changed under different rulers.', significance: 'Books, law, teaching, and religious networks were as important to urban life as gold and salt.', pointId: 'timbuktu', entity: 'Mali' },
      { year: 1468, section: 'IV · Songhai power', title: 'Songhai takes Timbuktu', description: 'Sunni Ali brought Timbuktu into an expanding Songhai state centered along the Niger. His campaigns and river forces built power across a strategic zone of farming, towns, and trade.', significance: 'Control of a celebrated city was one part of a wider regional contest, not the beginning of its history.', entity: 'Songhai', eventId: 'songhai-timbuktu' },
      { year: 1493, section: 'IV · Songhai power', title: 'Askia Muhammad reorganizes the empire', description: 'Askia Muhammad seized power, strengthened provincial administration, and cultivated ties with Muslim scholars and rulers. Songhai became one of the largest states in West African history before Moroccan invasion in 1591.', significance: 'Political centralization and scholarship reinforced one another but could not remove regional tensions or external threats.', entity: 'Songhai', eventId: 'timbuktu-manuscript' },
    ],
  },
  {
    id: 'alexander', title: 'Alexander and the successor world', subtitle: 'The Achaemenid setting, a decade of conquest, and three centuries of Hellenistic change', category: 'Empires & states', period: '518–100 BCE', estimatedMinutes: 5, color: '#e3bd55',
    introduction: 'Alexander’s conquests make sense only within the wealthy, connected Achaemenid world he attacked. His victories were astonishingly fast; the more durable story is how soldiers, dynasts, cities, and local societies reshaped the fragments afterward.',
    conclusion: 'Alexander destroyed the Achaemenid monarchy but did not replace it with a stable unified state. Successor kingdoms combined Macedonian dynasties with older institutions and local power, producing connected but contested Hellenistic worlds that later met expanding Roman and Parthian states.',
    steps: [
      { year: -518, section: 'I · The empire before Alexander', title: 'Persepolis stages Achaemenid kingship', description: 'Darius I began the monumental complex at Persepolis within an empire spanning many peoples and ecological zones. Provincial administration, tribute, roads, and negotiated local authority sustained royal power.', significance: 'Alexander invaded an established imperial system, not loose lands waiting to be unified.', entity: 'Achaemenid Empire', eventId: 'persepolis' },
      { year: -400, section: 'I · The empire before Alexander', title: 'A durable but contested imperial order', description: 'Achaemenid kings governed from several royal centers while managing revolts, court rivalries, and frontier wars. Greek cities were only one region on the empire’s western edge.', significance: 'Later Greek accounts magnified their own viewpoint; the empire’s scale and resilience require a wider lens.', entity: 'Achaemenid Empire' },
      { year: -331, section: 'II · Conquest', title: 'Achaemenid power breaks at Gaugamela', description: 'Alexander’s Macedonian-led army defeated Darius III near Gaugamela after earlier victories in Anatolia and the Levant. The road into the imperial heartlands opened, though resistance continued.', significance: 'One battle transformed dynastic control, but conquest still depended on treasuries, cities, officials, and loyalties.', entity: 'Empire of Alexander', eventId: 'gaugamela' },
      { year: -323, section: 'II · Conquest', title: 'An empire without a settled succession', description: 'Alexander died in Babylon after campaigns reaching Egypt, Central Asia, and the Indus. He left no adult heir or agreed system for governing the enormous realm.', significance: 'The speed of conquest had outpaced the construction of a durable political settlement.', entity: 'Empire of Alexander', eventId: 'alexander-death' },
      { year: -300, section: 'III · The successors', title: 'Rival dynasties divide the conquests', description: 'Generals and members of the royal household fought for decades. The Ptolemies secured Egypt, the Seleucids controlled much of western Asia, and Antigonid power emerged in Macedonia.', significance: 'The successor kingdoms were new states shaped by warfare, marriage, administration, and local negotiation.', entity: 'Seleucid Kingdom' },
      { year: -200, section: 'III · The successors', title: 'Hellenistic worlds become locally rooted', description: 'Greek-speaking royal courts and new or expanded cities coexisted with Egyptian, Babylonian, Iranian, Jewish, and many other communities. Cultural exchange never meant that difference or hierarchy disappeared.', significance: 'Hellenistic history is unequal interaction and adaptation, not a simple one-way spread of Greek culture.', entity: 'Ptolemaic Kingdom', pointId: 'alexandria' },
      { year: -100, section: 'IV · New powers close in', title: 'The successor map contracts', description: 'Roman intervention advanced in the Mediterranean while Parthian power reduced Seleucid control in Asia. Ptolemaic Egypt remained independent but was deeply entangled in Roman politics.', significance: 'Alexander’s political empire was brief; the institutions and connections formed after it lasted much longer.', entity: 'Ptolemaic Kingdom', pointId: 'alexandria' },
    ],
  },
  {
    id: 'egypt', title: 'Egypt and the Nile kingdoms', subtitle: 'Four millennia of state formation, fragmentation, conquest, and cultural endurance', category: 'Long histories', period: '4000–30 BCE', estimatedMinutes: 6, color: '#d5aa3f',
    introduction: '“Ancient Egypt” was not one unchanged civilization. Across thousands of years, rulers united and lost territory, capitals shifted, foreign dynasties governed, and communities continually remade language, religion, art, and relations with the Nile.',
    conclusion: 'Egyptian kingship ended under Roman rule, but Egyptian communities and cultural traditions did not. Temples, texts, languages, craft practices, and memories changed across Persian, Macedonian, Roman, Christian, and Islamic periods rather than stopping at a single boundary.',
    steps: [
      { year: -4000, section: 'I · Communities along the Nile', title: 'River, floodplain, and regional societies', description: 'Farming communities along the Nile developed distinct local traditions, exchanged goods, and competed for land and authority. The river connected regions while deserts and cataracts shaped movement.', significance: 'The landscape supported state formation, but political unity was a historical achievement rather than a natural inevitability.', entity: 'Egypt' },
      { year: -3000, section: 'II · Early unification', title: 'Kingship joins Upper and Lower Egypt', description: 'Around the turn of the third millennium BCE, rulers associated with southern centers consolidated control over the Nile valley and delta. Memphis became an important royal and administrative center.', significance: 'Unified kingship created institutions and symbols that later dynasties repeatedly claimed and reinvented.', entity: 'Egypt', pointId: 'memphis' },
      { year: -2560, section: 'III · The Old Kingdom', title: 'The Great Pyramid mobilizes a kingdom', description: 'The pyramid complex built for Khufu required skilled labor, food, transport, stoneworking, surveying, and administration on an extraordinary scale. It was part of a wider sacred and political landscape at Giza.', significance: 'Monuments reveal organized labor and royal ideology, not just the ambition of an individual ruler.', entity: 'Egypt', eventId: 'great-pyramid' },
      { year: -2000, section: 'IV · Collapse and reunification', title: 'Central power is rebuilt', description: 'Periods of strong kingship alternated with fragmentation and regional rule. Middle Kingdom rulers reunified much of Egypt, expanded administration, and projected power south into Nubia.', significance: 'Egyptian history was cyclical and contested; breakdown could lead to new forms of central authority.', entity: 'Egypt' },
      { year: -1500, section: 'V · The New Kingdom', title: 'Egypt becomes an imperial power', description: 'After expelling Hyksos rulers, New Kingdom pharaohs campaigned into Nubia and the eastern Mediterranean. Wealth flowed to royal projects and temple institutions, while diplomacy tied Egypt to other great powers.', significance: 'Egypt was embedded in an international Bronze Age world of war, marriage, gifts, and trade.', entity: 'Egypt' },
      { year: -1000, section: 'VI · Competing dynasties', title: 'Authority fragments again', description: 'Priestly institutions, regional rulers, Libyan dynasties, and Nubian kings competed for control. Egypt remained culturally productive even when no single court governed the entire Nile valley.', significance: 'Political fragmentation did not equal cultural disappearance or social collapse.', entity: 'Egypt' },
      { year: -500, section: 'VII · Within larger empires', title: 'Achaemenid kings rule Egypt', description: 'Persian rulers incorporated Egypt into the Achaemenid Empire while using and modifying Egyptian institutions and royal imagery. Revolts and periods of renewed local rule showed that control remained contested.', significance: 'Foreign dynasties often governed through Egyptian forms rather than replacing them wholesale.', entity: 'Achaemenid Empire' },
      { year: -300, section: 'VIII · A Macedonian dynasty', title: 'Alexandria anchors Ptolemaic Egypt', description: 'After Alexander’s conquest, the Ptolemaic dynasty ruled from Alexandria. Greek became central to administration, but Egyptian temples, priesthoods, languages, and royal traditions remained essential to power.', significance: 'Ptolemaic Egypt was both a Hellenistic kingdom and a transformation of much older Egyptian institutions.', entity: 'Ptolemaic Kingdom', pointId: 'alexandria' },
      { year: -30, section: 'IX · Roman annexation', title: 'A kingdom ends, a society continues', description: 'After the defeat of Cleopatra VII and Mark Antony, Octavian annexed Egypt as a Roman province. Its grain, taxes, cities, and temples became part of an imperial system centered elsewhere.', significance: 'The end of a dynasty is not the end of the people, beliefs, languages, and practices it had governed.', entity: 'Roman Empire', pointId: 'alexandria', dateLabel: '30 BCE' },
    ],
  },
  {
    id: 'china-dynasties', title: 'China: unity, division, and reinvention', subtitle: 'How successive dynasties rebuilt imperial government across changing frontiers', category: 'Long histories', period: '221 BCE–1949 CE', estimatedMinutes: 8, color: '#de6748',
    introduction: 'Chinese imperial history was not an unbroken line of identical dynasties. States repeatedly unified and divided, capitals shifted, frontiers moved, and institutions changed through encounters with steppe powers, regional societies, commercial growth, rebellion, and foreign conquest.',
    conclusion: 'Ideas of a unified realm and dynastic legitimacy endured, but every reunification created a different state. The 1911 revolution ended monarchy, while civil war, invasion, and revolution eventually produced the People’s Republic on the mainland in 1949 and a new political order.',
    steps: [
      { year: -221, section: 'I · First empire', title: 'Qin defeats the rival kingdoms', description: 'The king of Qin conquered the remaining Warring States and claimed a new title: First Emperor. His government standardized measures and writing practices while imposing harsh labor and military demands.', significance: 'The Qin created an influential model of territorial unification, even though their dynasty collapsed quickly.', entity: 'Qin', eventId: 'qin-unification' },
      { year: -138, section: 'II · Han consolidation', title: 'The Han court turns toward Central Asia', description: 'Han rulers moderated some Qin practices while preserving centralized institutions. Zhang Qian’s missions and campaigns in the northwest tied imperial strategy to Central Asian diplomacy and exchange.', significance: 'Imperial frontiers were zones of negotiation, migration, commerce, and war—not fixed ethnic boundaries.', entity: 'Han', eventId: 'zhang-qian' },
      { year: 105, section: 'II · Han consolidation', title: 'Paper becomes a court technology', description: 'Cai Lun was traditionally credited with reporting improvements to papermaking, part of a longer process of experimentation. Paper gradually became a practical medium for administration, scholarship, religion, and art.', significance: 'State capacity also depended on materials and knowledge, not only armies and borders.', entity: 'Han', eventId: 'han-paper' },
      { year: 300, section: 'III · Centuries of division', title: 'Regional states replace Han unity', description: 'After the Han collapsed, rival courts and migrating populations reshaped northern and southern China. Buddhism expanded through translation, patronage, pilgrimage, and monastic institutions.', significance: 'Division was not an empty interval; it generated new political, religious, and cultural forms.', mapNote: 'The source map generalizes the many Chinese regional states in this period.', source: { title: 'Encyclopaedia Britannica: Six Dynasties', url: 'https://www.britannica.com/event/Six-Dynasties' } },
      { year: 589, section: 'IV · Reunification', title: 'The Sui rebuild a single empire', description: 'Sui forces defeated the southern Chen and reunited much of China. Massive construction and military campaigns strengthened connections but placed extraordinary burdens on households.', significance: 'Reunification restored an imperial framework while the dynasty’s overreach helped bring its rapid fall.', entity: 'Sui Empire', eventId: 'sui-reunification' },
      { year: 800, section: 'V · Tang cosmopolitan power', title: 'Chang’an faces many worlds', description: 'Tang government extended influence deep into Central Asia before rebellion weakened central control. Chang’an drew diplomats, merchants, religious communities, artists, and goods from across Eurasia.', significance: 'Imperial Chinese history was made through international and frontier connections as well as an agrarian heartland.', entity: 'Tang Empire', pointId: 'changan' },
      { year: 960, section: 'VI · Song transformation', title: 'A new dynasty reunifies most of China', description: 'The Song reduced the independent power of military commanders and built an extensive civil bureaucracy. Printing, urbanization, commerce, education, and technological change reshaped society.', significance: 'Political strength cannot be measured by territorial size alone; Song influence far exceeded its shifting frontiers.', entity: 'Song Empire', eventId: 'song-founded' },
      { year: 1279, section: 'VII · Conquest and incorporation', title: 'The Yuan completes the conquest', description: 'Khubilai Khan’s forces ended the Southern Song and ruled China as part of a wider Mongol imperial world. The government categorized populations unequally while moving people and expertise across Eurasia.', significance: 'Foreign conquest transformed Chinese institutions and also transformed the Mongol rulers who governed through them.', entity: 'Mongol Empire' },
      { year: 1405, section: 'VIII · Ming restoration', title: 'Ming fleets project power overseas', description: 'The Ming replaced Yuan rule and rebuilt institutions under a native dynasty. Zheng He’s expeditions displayed imperial authority across established Southeast Asian and Indian Ocean networks.', significance: 'The early Ming looked both inland and overseas; later restrictions did not make China isolated from world trade.', entity: 'Ming Chinese Empire', eventId: 'zheng-he' },
      { year: 1783, section: 'IX · Qing imperial expansion', title: 'A Manchu-ruled, multiethnic empire', description: 'Qing rulers governed China while expanding into Inner Asia through military conquest, alliances, and distinct administrative systems. The dynasty represented itself differently to Chinese, Tibetan, Mongol, and other subjects.', significance: 'The Qing was not simply another identical dynasty; it was a large imperial formation with multiple traditions.', entity: 'Qing Empire', pointId: 'beijing' },
      { year: 1949, section: 'X · Revolution', title: 'The People’s Republic is proclaimed', description: 'After the 1911 fall of the Qing, decades of warlord rule, Japanese invasion, and civil war transformed the landscape. Communist victory established a new government in Beijing while the Nationalist government retreated to Taiwan.', significance: 'Imperial unity gave way to competing modern projects of nation, revolution, sovereignty, and development.', entity: 'China', eventId: 'prc-founded' },
    ],
  },
  {
    id: 'south-asia', title: 'States and ideas across South Asia', subtitle: 'Empire, regional power, religious change, and connected cities from Maurya to Mughal rule', category: 'Empires & states', period: '300 BCE–1700 CE', estimatedMinutes: 7, color: '#cb6f9d',
    introduction: 'No empire ever made South Asia politically or culturally uniform. This story follows moments when large states connected regions and when powerful regional courts, temples, cities, merchants, and religious communities reshaped the subcontinent.',
    conclusion: 'South Asian political history alternated among large empires, regional kingdoms, frontier states, and local powers. Maurya, Gupta, Chola, Delhi, Vijayanagara, and Mughal institutions were distinct; together they show how rule was repeatedly rebuilt through plural societies and wider Asian networks.',
    steps: [
      { year: -300, section: 'I · Mauryan unification', title: 'Pataliputra anchors a large imperial state', description: 'The Mauryan dynasty drew much of the subcontinent into a system governed through provincial centers, officials, taxation, and military power. Pataliputra stood within the fertile and connected Ganges plain.', significance: 'The Mauryan realm became an important model of large-scale government, but regional authority remained essential.', entity: 'Mauryan Empire', pointId: 'pataliputra' },
      { year: -261, section: 'I · Mauryan unification', title: 'Kalinga changes Ashoka’s public kingship', description: 'Ashoka’s conquest caused mass death, deportation, and suffering. His later inscriptions expressed remorse and promoted dhamma—an ethical program of welfare, restraint, and respect—without abandoning imperial government.', significance: 'The edicts let us hear a ruler publicly confront the violence that sustained his own power.', entity: 'Mauryan Empire', eventId: 'kalinga' },
      { year: 300, section: 'II · Gupta and regional worlds', title: 'A new northern dynasty expands', description: 'Gupta rulers built a powerful state across much of northern India through warfare, alliances, tribute, and regional administration. Their court patronage supported Sanskrit literature, religious institutions, art, mathematics, and astronomy.', significance: '“Golden age” labels highlight achievements but can obscure inequality and the creativity of other regions.', entity: 'Gupta Empire' },
      { year: 499, section: 'II · Gupta and regional worlds', title: 'Aryabhata writes a mathematical cosmos', description: 'Aryabhata completed the Aryabhatiya, a concise work on arithmetic, algebra, trigonometry, and astronomy. Its methods influenced later scholars in South Asia and, through translation and exchange, beyond it.', significance: 'Intellectual history moved through teachers, texts, commentary, and translation as well as royal borders.', entity: 'Gupta Empire', eventId: 'gupta-aryabhata' },
      { year: 1010, section: 'III · Southern courts and oceans', title: 'Chola power is built in stone and at sea', description: 'Rajaraja I completed the Brihadishvara Temple within a wealthy agrarian and temple-centered state. Chola campaigns and merchant networks also reached Sri Lanka and Southeast Asian waters.', significance: 'South Indian power joined local landholding and ritual authority to an active Indian Ocean world.', entity: 'Chola state', eventId: 'chola-temple' },
      { year: 1300, section: 'IV · Sultanates and regional states', title: 'Delhi governs through a Persianate court', description: 'Successive Delhi sultanates ruled large parts of northern India with cavalry armies, revenue systems, urban elites, and Persianate political culture. Their reach varied and faced continual regional resistance.', significance: 'Islamic rule developed through migration, conflict, conversion, patronage, and interaction with existing societies.', entity: 'Sultanate of Delhi' },
      { year: 1400, section: 'IV · Sultanates and regional states', title: 'Power remains regionally diverse', description: 'Delhi’s authority contracted while Bengal, the Deccan sultanates, Vijayanagara, and other states competed and prospered. Courts supported architecture, vernacular languages, temples, mosques, trade, and new military systems.', significance: 'A single imperial outline cannot represent the subcontinent’s many simultaneous centers.', entity: 'Sultanate of Delhi' },
      { year: 1492, section: 'V · Vijayanagara', title: 'Hampi commands a southern empire', description: 'Vijayanagara’s capital combined temples, markets, palaces, fortifications, waterworks, and agricultural hinterlands on a monumental scale. Its rulers negotiated with local chiefs and competed with Deccan sultanates.', significance: 'Urban splendor depended on regional networks of labor, land, devotion, commerce, and warfare.', entity: 'Vijayanagara', pointId: 'hampi' },
      { year: 1526, section: 'VI · The Mughal synthesis', title: 'Babur wins at Panipat', description: 'Babur defeated Ibrahim Lodi with field artillery and mobile tactics, establishing a foothold for Mughal rule. His successors—notably Akbar—built the more durable imperial institutions that followed.', significance: 'A battle mattered, but negotiation, revenue reform, marriage, conquest, and regional partnerships made the empire.', entity: 'Mughal Empire', eventId: 'panipat' },
      { year: 1700, section: 'VI · The Mughal synthesis', title: 'A vast empire approaches its limits', description: 'Mughal authority reached its greatest extent under Aurangzeb, but long wars, succession struggles, fiscal pressure, and powerful regional groups strained central rule. Cultural and commercial life remained dynamic.', significance: 'Political fragmentation was a redistribution of power, not a simple civilizational decline.', entity: 'Mughal Empire' },
    ],
  },
  {
    id: 'mesoamerica-and-andes', title: 'Cities and empires of the Americas', subtitle: 'Olmec centers, Maya kingdoms, Teotihuacan, Mexica power, and Tawantinsuyu', category: 'Cities & states', period: '1500 BCE–1530 CE', estimatedMinutes: 7, color: '#58a85b',
    introduction: 'The pre-contact Americas contained many independent histories, not one ladder toward “civilization.” This story pairs Mesoamerican and Andean cases to show different traditions of urbanism, writing, agriculture, political authority, and imperial expansion.',
    conclusion: 'Spanish invaders did not defeat passive or isolated empires. They entered contested political worlds and relied on Indigenous enemies and allies, while epidemic disease magnified catastrophe. Maya, Nahua, Quechua, Aymara, and many other peoples survived conquest and remain living communities.',
    steps: [
      { year: -1500, section: 'I · Early Mesoamerican centers', title: 'Communities reshape the Gulf lowlands', description: 'Farming villages grew across Mesoamerica long before the political centers later called Olmec. Regional exchange moved obsidian, jade, ceramics, food, and ideas through varied landscapes.', significance: 'Complex societies developed through deep local histories rather than appearing suddenly with famous monuments.', entity: 'Olmec' },
      { year: -800, section: 'I · Early Mesoamerican centers', title: 'La Venta flourishes', description: 'La Venta’s communities built earthen platforms, arranged offerings, and commissioned colossal stone sculpture. Its imagery participated in wider networks without making it the single “mother culture” of Mesoamerica.', significance: 'Influence traveled in several directions among contemporary societies.', entity: 'Olmec', eventId: 'olmec-la-venta' },
      { year: 200, section: 'II · Great cities and Maya kings', title: 'Teotihuacan becomes a metropolis', description: 'Teotihuacan grew into one of the world’s largest cities, organized around monumental avenues, apartment compounds, workshops, and ritual spaces. Its influence reached far beyond the Valley of Mexico.', significance: 'Urban scale emerged without a readable royal history, reminding us that cities can be organized in unfamiliar ways.', pointId: 'teotihuacan' },
      { year: 292, section: 'II · Great cities and Maya kings', title: 'Tikal records dynastic rule', description: 'An early dated monument at Tikal depicts a ruler within a Maya world of competing kingdoms. Kings used writing, calendars, warfare, marriage, and public ceremony to make claims about sacred authority.', significance: 'The Maya were never one empire; their cities formed changing alliances and rivalries.', entity: 'Maya chiefdoms and states', eventId: 'tikal-stela' },
      { year: 800, section: 'III · Change without disappearance', title: 'Classic Maya political systems fragment', description: 'Many southern lowland royal courts declined or were abandoned during the eighth and ninth centuries amid warfare, drought, and political stress. Maya populations and states continued elsewhere, especially in the north.', significance: 'The end of particular dynasties or cities was not the extinction of Maya people or culture.', entity: 'Maya city-states', pointId: 'tikal' },
      { year: 1400, section: 'IV · New imperial capitals', title: 'Tenochtitlan leads a tribute empire', description: 'The Mexica-led Triple Alliance expanded through warfare and demanded tribute from many subject cities. Its island capital was a vast center of markets, causeways, temples, canals, and intensive agriculture.', significance: 'Imperial resentment later gave Spanish invaders indispensable Indigenous allies.', entity: 'Aztec Empire', pointId: 'tenochtitlan-city' },
      { year: 1450, section: 'IV · New imperial capitals', title: 'The Inca build Tawantinsuyu', description: 'From Cusco, Inca rulers rapidly expanded across the Andes through conquest, diplomacy, resettlement, roads, labor obligations, and alliances. They governed ecological and linguistic diversity without an alphabetic script.', significance: 'Imperial infrastructure joined distant regions while extracting labor and provoking resistance.', entity: 'Inca Empire', pointId: 'cusco' },
      { year: 1521, section: 'V · Invasion and alliance', title: 'Tenochtitlan falls', description: 'Spanish forces and tens of thousands of Indigenous allies besieged the capital amid a devastating smallpox epidemic. The fall ended Triple Alliance rule but not Nahua communities or their political agency.', significance: 'Conquest was a coalition war within Mesoamerica as well as a European invasion.', entity: 'Aztec Empire', eventId: 'tenochtitlan' },
      { year: 1530, section: 'V · Invasion and alliance', title: 'Civil war opens the Andes to invasion', description: 'A succession war between Atahualpa and Huáscar had divided Tawantinsuyu when Pizarro’s expedition arrived. Spanish forces exploited rivalries and captured Atahualpa, but resistance continued for decades.', significance: 'The imperial court fell quickly; colonial control over Andean societies did not.', entity: 'Inca Empire', pointId: 'machu-picchu' },
    ],
  },
  {
    id: 'pacific-worlds', title: 'Pacific worlds', subtitle: 'Cultivation, engineering, voyaging, ceremony, and Indigenous states across the world’s largest ocean', category: 'People & movement', period: '5000 BCE–1810 CE', estimatedMinutes: 6, color: '#3d9fc4',
    introduction: 'The Pacific is not an empty space separating “remote” islands. It is a region of connected homelands whose peoples developed agriculture, engineered landscapes, read winds and stars, and sustained political and ceremonial relationships across immense distances.',
    conclusion: 'Pacific settlement unfolded through deliberate voyages, return travel, innovation, and adaptation—not accidental drift. Colonial borders later obscured older connections, but Indigenous knowledge, sovereignty, languages, and stewardship continue across the region.',
    steps: [
      { year: -5000, section: 'I · Engineered homelands', title: 'Cultivation reshapes Kuk', description: 'Communities in the New Guinea highlands repeatedly modified wetland margins with mounds, ditches, and drainage systems to cultivate useful plants. The landscape preserves a long sequence of experimentation rather than a single invention.', significance: 'Food production developed independently in New Guinea through generations of local knowledge.', eventId: 'kuk-agriculture' },
      { year: -4600, section: 'I · Engineered homelands', title: 'Gunditjmara people manage water at Budj Bim', description: 'In southeastern Australia, Gunditjmara communities engineered channels, weirs, and ponds within a volcanic landscape to manage kooyang, or short-finned eel. The system formed part of a continuing cultural landscape.', significance: 'Complex engineering and settled resource management challenge old colonial myths about Aboriginal economies.', pointId: 'budj-bim', dateLabel: 'From about 4600 BCE' },
      { year: -2000, section: 'II · Austronesian movement', title: 'Seafaring languages and lifeways spread', description: 'Across many generations, Austronesian-speaking communities moved through island Southeast Asia and into the Pacific. Crops, animals, boat technologies, languages, and social practices changed as travelers met existing populations.', significance: 'Expansion was branching and interactive, not a single migration by one uniform people.', routeId: 'austronesian' },
      { year: -1000, section: 'III · Remote Oceania', title: 'Lapita communities cross into new archipelagos', description: 'Seafarers associated with Lapita pottery settled islands from the Bismarck Archipelago through Vanuatu, Fiji, Tonga, and Samoa. They carried crops and technologies while adapting to radically different island ecologies.', significance: 'These voyages required planning, navigational expertise, social networks, and viable new communities.', eventId: 'lapita-remote-oceania' },
      { year: 1000, section: 'IV · Inter-island sacred geographies', title: 'Taputapuātea links a voyaging world', description: 'The marae complex on Raʻiātea became a major political and ceremonial center in eastern Polynesia. Genealogies and voyaging traditions connected it with islands across a shared oceanic geography.', significance: 'Political and sacred relationships could cross sea routes without forming a centralized territorial empire.', pointId: 'taputapuatea' },
      { year: 1200, section: 'IV · Inter-island sacred geographies', title: 'Nan Madol takes monumental form', description: 'Pohnpeian builders created more than one hundred artificial islets with basalt architecture for residence, ritual, administration, and burial. The center expressed Saudeleur authority and drew on island resources and labor.', significance: 'Monumentality in Oceania took forms adapted to reefs, lagoons, and local political traditions.', eventId: 'nan-madol' },
      { year: 1275, section: 'V · The last great settlement horizon', title: 'Voyagers settle Aotearoa', description: 'Deliberate expeditions from East Polynesia established permanent settlements between about 1250 and 1300. Communities adapted horticulture, architecture, food gathering, and political life to a cooler and larger land.', significance: 'Māori society developed through both ancestral Pacific knowledge and innovation in a new homeland.', entity: 'Māori', eventId: 'aotearoa-settlement' },
      { year: 1810, section: 'VI · Indigenous state formation', title: 'Kamehameha unifies the Hawaiian Islands', description: 'Kamehameha I combined warfare, diplomacy, foreign weapons, and negotiated recognition to bring the islands under one kingdom. Unification occurred amid accelerating trade and foreign presence in the North Pacific.', significance: 'Hawaiian centralization was an Indigenous project shaped by, but not reducible to, outside contact.', eventId: 'hawaiian-unification' },
    ],
  },
  {
    id: 'indigenous-north-america', title: 'Indigenous centers of North America', subtitle: 'Earthworks, great houses, mound cities, exchange, and continuity before and after European arrival', category: 'Cities & communities', period: '100 BCE–1492 CE', estimatedMinutes: 6, color: '#b8844d',
    introduction: 'North America before European colonization held many distinct political, ceremonial, and economic worlds. This story follows several—not as stages of one civilization, but as communities whose landscapes, networks, and descendants have their own histories.',
    conclusion: 'Hopewell earthworks, Chaco, Cahokia, and Pueblo towns belonged to different peoples and eras. None should be treated as a “lost race.” Their histories connect to living Indigenous nations whose sovereignty and knowledge are central to interpreting these places today.',
    steps: [
      { year: -100, section: 'I · Gathering landscapes', title: 'Communities build networks without a capital', description: 'Across the Ohio River valleys, dispersed communities gathered at earthwork centers for ceremony, exchange, and social relationships. Materials traveled from the Great Lakes, Appalachians, Gulf Coast, and Rocky Mountains.', significance: 'Wide connection did not require a centralized empire or a dense permanent city.', entity: 'Hopewell Culture' },
      { year: 200, section: 'I · Gathering landscapes', title: 'Geometry links earth and sky', description: 'Hopewell ceremonial earthworks combined enormous circles, squares, octagons, and embankments with precise planning. Some alignments marked lunar cycles, while burial and gathering practices varied across sites.', significance: 'Monumental knowledge was renewed by communities whose political organization differed from familiar state models.', entity: 'Hopewell Culture', eventId: 'hopewell-earthworks' },
      { year: 800, section: 'II · Southwestern traditions', title: 'Many Pueblo histories take shape', description: 'Across the Southwest, communities developed varied villages, farming systems, ceramics, trade, and ceremonial practices. Mogollon, Hohokam, Ancestral Pueblo, and other labels describe overlapping archaeological traditions.', significance: 'Regional diversity matters; one map label cannot stand in for many peoples and languages.', entity: 'Mogollon' },
      { year: 1050, section: 'III · Chaco', title: 'Great houses anchor a regional world', description: 'Chaco Canyon contained multi-storey great houses, ceremonial spaces, engineered roads, and connections to distant communities. Construction required timber, masonry skill, food, and coordinated labor in a demanding environment.', significance: 'Chaco belonged to a broad social, ceremonial, and exchange landscape.', eventId: 'chaco-height' },
      { year: 1100, section: 'IV · Cahokia', title: 'A mound city rises beside the Mississippi', description: 'Cahokia grew rapidly around plazas, neighborhoods, workshops, and monumental earthen mounds. Its regional influence reached along river systems, though people experienced its concentrated authority in different ways.', significance: 'Large urban life developed north of Mexico through Indigenous institutions and exchange networks.', eventId: 'cahokia-peak' },
      { year: 1200, section: 'IV · Cahokia', title: 'Urban concentration changes', description: 'Cahokia’s population later declined as political relationships, environmental pressures, and settlement patterns changed. Communities across the Mississippian world continued to build towns, mounds, and regional polities.', significance: 'A city’s decline is not the disappearance of the societies connected to it.', pointId: 'cahokia' },
      { year: 1400, section: 'V · Pueblo movement and continuity', title: 'Communities reorganize across the Southwest', description: 'People moved from some ancestral centers and joined or established new settlements. Oral histories, archaeology, architecture, and language connect present-day Pueblo communities with these wider ancestral landscapes.', significance: 'Migration can be a form of adaptation and continuity rather than mysterious abandonment.', entity: 'Pueblos', pointId: 'chaco-culture' },
      { year: 1492, section: 'VI · Before invasion', title: 'Sovereign worlds meet a colonial horizon', description: 'On the eve of sustained European colonization, North America contained hundreds of nations with distinct governments, languages, trade relationships, and territorial histories. Later epidemics and invasion would transform—but not erase—them.', significance: 'The continent was neither empty nor waiting; its peoples remain political communities in the present.', entity: 'Taos Pueblo' },
    ],
  },
  {
    id: 'caliphates', title: 'The early caliphates and their worlds', subtitle: 'Community, conquest, contested authority, cities, scholarship, and regional dynasties', category: 'Religion & states', period: '622–1200 CE', estimatedMinutes: 6, color: '#58a966',
    introduction: 'The caliphates were political states, religious claims, and diverse societies—not one unchanged empire. Their rapid expansion joined older Roman, Sasanian, Arab, Berber, Persian, Central Asian, and other worlds while disputes over legitimate rule took lasting forms.',
    conclusion: 'By 1200 no single caliph governed most Muslim societies, yet claims to legitimacy and networks of law, learning, trade, pilgrimage, and worship crossed political borders. Regionalization was not the end of an Islamic world; it was one of the ways that world developed.',
    steps: [
      { year: 622, section: 'I · A community in Medina', title: 'The Hijra marks a new beginning', description: 'Muhammad and his followers migrated from Mecca to Medina, where the community developed new political and social institutions. The journey later became the epoch of the Islamic calendar.', significance: 'The Hijra joined religious commitment to the practical work of building and governing a community.', eventId: 'hijra' },
      { year: 632, section: 'II · Succession and expansion', title: 'Leadership becomes contested', description: 'Muhammad’s death raised urgent questions about who should lead and on what authority. Early caliphs oversaw expansion beyond Arabia, while internal conflicts helped form enduring Sunni and Shiʻa traditions.', significance: 'Disagreement over succession was both political and religious, and later communities remembered it differently.', dateLabel: 'From 632 CE', mapNote: 'The map uses the nearest broad reconstruction; early expansion changed rapidly.', source: { title: 'Encyclopaedia Britannica: Caliphate', url: 'https://www.britannica.com/place/Caliphate' } },
      { year: 691, section: 'III · Umayyad empire', title: 'The Dome of the Rock makes an imperial statement', description: 'Caliph Abd al-Malik completed the sanctuary in Jerusalem amid civil war and consolidation. Its inscriptions and architecture placed the new Islamic polity within—and in argument with—older sacred traditions.', significance: 'Buildings could communicate theology, legitimacy, and confidence across a diverse empire.', entity: 'Umayyad Caliphate', eventId: 'umayyad-dome' },
      { year: 700, section: 'III · Umayyad empire', title: 'Rule stretches across three continents', description: 'Umayyad armies and governors connected Iberia, North Africa, the Middle East, and Central Asian frontiers. Arabic administrative reform advanced unevenly, while Christians, Jews, Zoroastrians, and others remained large parts of the population.', significance: 'Conquest was rapid; social, linguistic, and religious change unfolded over much longer periods.', entity: 'Umayyad Caliphate' },
      { year: 762, section: 'IV · Abbasid revolution', title: 'Baghdad becomes a new capital', description: 'The Abbasids overthrew the Umayyads in most of the empire and founded Baghdad near older Mesopotamian centers. Their court drew heavily on Persian administrative practices and far-reaching commercial networks.', significance: 'A change of dynasty shifted the center east and created new coalitions without ending older tensions.', entity: 'Abbasid Caliphate', eventId: 'baghdad-founded' },
      { year: 800, section: 'V · A connected intellectual world', title: 'Learning moves through translation and debate', description: 'Scholars working in Arabic translated and extended Greek, Persian, Syriac, and Indian knowledge in medicine, mathematics, philosophy, astronomy, and other fields. Learning also lived beyond courts in households, libraries, and religious institutions.', significance: 'Knowledge accumulated through multilingual collaboration, criticism, and new research—not passive preservation.', entity: 'Abbasid Caliphate', pointId: 'baghdad-city' },
      { year: 1000, section: 'VI · Several centers of authority', title: 'Caliphs compete in Baghdad, Cairo, and Córdoba', description: 'Abbasid caliphs remained in Baghdad while Fatimid rulers claimed the title in Cairo and Umayyad descendants had declared a caliphate in al-Andalus. Regional dynasties exercised much of the military power.', significance: 'A shared religious vocabulary did not create one political state or erase regional difference.', entity: 'Fatimid Caliphate', pointId: 'cordoba' },
      { year: 1200, section: 'VII · A plural political world', title: 'Networks outlast imperial unity', description: 'Sultans and regional dynasties governed most territories once ruled directly by early caliphs. Pilgrimage, commerce, scholarship, legal schools, Sufi networks, and literary culture still connected distant communities.', significance: 'Political fragmentation and far-reaching civilizational connection could coexist and reinforce one another.', entity: 'Fatimid Caliphate' },
    ],
  },
  {
    id: 'mongols', title: 'The Mongol century', subtitle: 'Steppe coalition, devastating conquest, connected khanates, and enduring successor traditions', category: 'Empires & movement', period: '1200–1400 CE', estimatedMinutes: 6, color: '#4aa17a',
    introduction: 'The Mongol Empire joined more of Eurasia under related rulers than any earlier land empire. It did so through extraordinary military violence, then governed through local institutions, mobile courts, taxation, protected routes, religious patronage, and the forced movement of skilled people.',
    conclusion: 'The unified empire fragmented quickly, but Mongol-ruled states reshaped China, Iran, Central Asia, Russia, and the steppe. Their political traditions continued through successor dynasties, while the same connections that moved merchants and knowledge also moved armies, captives, and disease.',
    steps: [
      { year: 1200, section: 'I · Before the empire', title: 'Steppe politics are built through relationships', description: 'Pastoral communities organized around households, lineages, leaders, seasonal movement, trade, and warfare. Temüjin rose by making and breaking alliances in a competitive landscape rather than uniting a timeless, uniform “tribe.”', significance: 'The empire grew from contingent political choices and coalitions, not inevitable nomadic expansion.', entity: 'Mongol Empire' },
      { year: 1206, section: 'II · A new coalition', title: 'Temüjin is proclaimed Chinggis Khan', description: 'A great assembly recognized Temüjin as supreme ruler after years of conflict. He redistributed followers, promoted loyal commanders, and organized units that crossed older affiliations.', significance: 'Reorganization turned personal victory into a structure capable of sustained expansion.', entity: 'Mongol Empire', eventId: 'chinggis-khan' },
      { year: 1227, section: 'III · Conquest', title: 'Campaigns overwhelm neighboring states', description: 'Mongol armies defeated steppe rivals, the Jin and Western Xia frontiers, and the Khwarazmian Empire. Cities that resisted could face mass killing, enslavement, and destruction; others negotiated surrender.', significance: 'The empire’s celebrated connectivity was created through coercion on a catastrophic scale.', entity: 'Mongol Empire', dateLabel: 'By 1227 CE' },
      { year: 1279, section: 'IV · Largest reach', title: 'Related rulers span most of Eurasia', description: 'Khubilai’s Yuan forces completed the conquest of the Southern Song while other Chinggisid branches ruled Central Asia, Iran, and the western steppe. Formal unity had weakened even as family legitimacy remained shared.', significance: 'The empire at maximum extent was already a family of competing imperial states.', entity: 'Mongol Empire' },
      { year: 1300, section: 'V · Successor khanates', title: 'Regional courts adopt different strategies', description: 'The Yuan, Ilkhanate, Chagatai Khanate, and Golden Horde governed distinct populations and economies. Their rulers used Chinese, Persian, Islamic, Turkic, Rus’, and other officials and institutions.', significance: 'Mongol rule changed through the societies it conquered; there was no single administrative template.', entity: 'Ilkhanate', routeId: 'silk-roads' },
      { year: 1320, section: 'VI · Movement across the khanates', title: 'Merchants, envoys, and specialists travel', description: 'Relay stations, passports, patronage, and protected corridors helped some travelers cross great distances. Rulers also deported artisans and experts, while armies and tribute moved under compulsion.', significance: 'Mobility could be opportunity, diplomacy, exile, enslavement, or state policy depending on who moved and why.', entity: 'Mongol Empire', routeId: 'silk-roads', dateLabel: 'Early 14th century' },
      { year: 1347, section: 'VI · Movement across the khanates', title: 'Disease follows connected routes', description: 'The plague pandemic known as the Black Death spread across Eurasian and Mediterranean networks during the fourteenth century. Its precise paths remain debated, but movement and dense exchange helped carry it between regions.', significance: 'Connectivity produced vulnerability as well as prosperity and cultural exchange.', entity: 'Mongol Empire', routeId: 'silk-roads', dateLabel: 'From the 1340s' },
      { year: 1400, section: 'VII · Successor legacies', title: 'Timur builds a new conquest empire', description: 'Timur claimed the prestige of the Chinggisid order without being a direct male-line descendant of Chinggis Khan. His campaigns were destructive, while his court at Samarkand patronized architecture, scholarship, and art.', significance: 'Mongol political legitimacy remained powerful even where the original khanates had fractured.', entity: 'Timurid Empire', pointId: 'samarkand' },
    ],
  },
  {
    id: 'colonialism', title: 'Oceanic empires and decolonization', subtitle: 'Invasion, forced labor and movement, Indigenous resistance, partition, and unfinished independence', category: 'Empire & resistance', period: '1492–1957 CE', estimatedMinutes: 8, color: '#5d96cf',
    introduction: 'European oceanic empires were not created by voyages alone. They grew through military alliances, disease, land seizure, coerced labor, enslavement, commercial monopolies, settlement, and local intermediaries—and they were resisted from the beginning.',
    conclusion: 'Formal independence dismantled legal empire without undoing every border, economic dependency, racial hierarchy, displacement, or cultural loss colonialism produced. Decolonization remains a political and intellectual process, while Indigenous sovereignty cannot be reduced to postcolonial nation-states.',
    steps: [
      { year: 1492, section: 'I · Atlantic invasion', title: 'A crossing begins sustained colonization', description: 'Columbus’s Castilian-sponsored voyage reached Caribbean societies already connected through their own regional networks. Ensuing conquest, forced labor, settlement, and epidemic disease produced demographic catastrophe.', significance: 'The voyage matters not as a heroic “discovery” but as the opening of a violent and unequal Atlantic system.', eventId: 'atlantic-1492' },
      { year: 1498, section: 'II · Armed trade in the Indian Ocean', title: 'Portuguese fleets reach India', description: 'Vasco da Gama entered a commercial world linking East Africa, Arabia, South Asia, and Southeast Asia. Portuguese rulers then used ships, cannon, fortresses, and licensing systems to seize strategic advantages.', significance: 'Europeans did not create Indian Ocean trade; they introduced a new armed imperial competitor.', entity: 'Portugal', eventId: 'da-gama' },
      { year: 1521, section: 'III · Conquest through coalition', title: 'Tenochtitlan falls', description: 'Spanish forces depended on large Indigenous alliances against the Mexica-led empire, while smallpox devastated the region. Colonial rule then redistributed land, labor, and religious authority through continuing negotiation and violence.', significance: 'Conquest was neither a tiny European victory nor a simple story of Indigenous unity against outsiders.', entity: 'Aztec Empire', eventId: 'tenochtitlan' },
      { year: 1600, section: 'IV · A connected system of coercion', title: 'Plantations and mines reorder Atlantic worlds', description: 'European colonies extracted silver, sugar, tobacco, and other commodities through Indigenous tribute, forced labor, and the mass enslavement of Africans. Merchants, states, and consumers across several continents profited.', significance: 'Colonial wealth depended on coerced movement and labor, not only navigation or exchange.', entity: 'Portugal', source: { title: 'Smithsonian: Transatlantic Slave Trade', url: 'https://nmaahc.si.edu/explore/stories/transatlantic-slave-trade' } },
      { year: 1804, section: 'V · Revolution against slavery', title: 'Haiti defeats French colonial rule', description: 'Enslaved and free people in Saint-Domingue fought a complex revolution that abolished slavery and defeated major European armies. Haiti declared independence as the first state created by a successful slave revolution.', significance: 'The revolution transformed arguments about freedom while slaveholding powers tried to isolate the new country.', eventId: 'haiti-independence' },
      { year: 1815, section: 'VI · Empire changes form', title: 'Independence expands across the Americas', description: 'Wars and revolutions ended most Iberian colonial governments in mainland Latin America, but new states inherited social hierarchies, contested borders, and pressures on Indigenous lands. European commercial influence persisted.', significance: 'Political sovereignty did not automatically create social equality or end colonial patterns.', focus: { lat: 10.48, lng: -66.9 }, source: { title: 'Encyclopaedia Britannica: Latin American independence', url: 'https://www.britannica.com/place/Latin-America/The-independence-of-Latin-America' } },
      { year: 1884, section: 'VII · Partition of Africa', title: 'European states set rules without Africans', description: 'At the Berlin Conference, European powers negotiated principles for colonial claims and Congo trade without African representation. Military invasions and local resistance—not lines drawn in one room alone—then shaped occupation.', significance: 'The conference accelerated an imperial process whose borders and unequal structures had long afterlives.', eventId: 'berlin-conference' },
      { year: 1914, section: 'VIII · A world of empires', title: 'Colonial subjects enter a global war', description: 'European empires mobilized soldiers, laborers, taxes, food, and raw materials from colonies during the First World War. Fighting spread into Africa, the Middle East, Asia, and the Pacific.', significance: 'The “world” in world war included colonized people whose service later strengthened anti-colonial claims.', entity: 'France', source: { title: 'Imperial War Museums: Empires at war', url: 'https://www.iwm.org.uk/history/first-world-war' } },
      { year: 1947, section: 'IX · Independence and partition', title: 'British rule in South Asia ends', description: 'India and Pakistan became independent as colonial power transferred authority through partition. Mass migration, communal violence, and unresolved territorial disputes accompanied the achievement of sovereignty.', significance: 'Decolonization could be both liberation and a traumatic reorganization imposed under severe time pressure.', entity: 'India', eventId: 'india-independence' },
      { year: 1957, section: 'IX · Independence and partition', title: 'Ghana becomes independent', description: 'Ghana’s independence under Kwame Nkrumah marked a major postwar breakthrough in sub-Saharan Africa. Nkrumah tied national sovereignty to pan-African cooperation and wider continental liberation.', significance: 'Independence was not gifted by withdrawing empires; it followed organizing, strikes, negotiation, and pressure.', entity: 'Ghana', eventId: 'ghana-independence' },
    ],
  },
  {
    id: 'revolutions', title: 'Atlantic revolutions—and their limits', subtitle: 'Rights, slavery, sovereignty, race, and empire from North America to Haiti', category: 'Revolutions', period: '1776–1815 CE', estimatedMinutes: 5, color: '#cc79a7',
    introduction: 'Late eighteenth-century revolutions circulated claims about liberty and popular sovereignty across an Atlantic shaped by slavery and empire. Different groups used the same language toward radically different ends, and rights declared in theory were restricted in practice.',
    conclusion: 'The revolutions transformed sovereignty and law, but they did not produce one path to freedom. Haiti pushed emancipation farthest and faced the harshest punishment, while slavery, colonialism, Indigenous dispossession, and gender exclusion survived other declarations of universal rights.',
    steps: [
      { year: 1776, section: 'I · Independence and contradiction', title: 'Thirteen colonies declare independence', description: 'Colonial representatives justified separation from Britain through natural rights and government by consent. The new claim coexisted with racial slavery, limits on political participation, and pressure on Indigenous lands.', significance: 'A universal political language entered a society that denied its promises to much of the population.', entity: 'United States of America', eventId: 'declaration' },
      { year: 1783, section: 'I · Independence and contradiction', title: 'A republic secures international recognition', description: 'The peace settlement recognized United States independence and transferred British claims across vast Indigenous homelands without Indigenous consent. The confederation still faced debt, interstate conflict, and questions about federal power.', significance: 'Revolution created sovereignty for one state while endangering the sovereignty of others.', entity: 'United States of America' },
      { year: 1789, section: 'II · Revolution in France', title: 'The Bastille becomes a symbol', description: 'Economic crisis, elite conflict, popular mobilization, and demands for representation overturned the old order. The Declaration of the Rights of Man announced equality before law while excluding women from political citizenship.', significance: 'Revolution expanded rights claims and immediately opened battles over who counted as a citizen.', entity: 'France', eventId: 'bastille' },
      { year: 1791, section: 'III · Revolution in Saint-Domingue', title: 'Enslaved people rise', description: 'A massive uprising began in France’s richest Caribbean colony after free people of color, white colonists, and officials had already contested revolutionary rights. Enslaved rebels made emancipation unavoidable.', significance: 'Those most brutally excluded from Atlantic liberty turned abstract rights into a struggle against slavery.', focus: { lat: 19.45, lng: -72.68 }, source: { title: 'Encyclopaedia Britannica: Haitian Revolution', url: 'https://www.britannica.com/topic/Haitian-Revolution' } },
      { year: 1794, section: 'III · Revolution in Saint-Domingue', title: 'France abolishes slavery—temporarily', description: 'The French National Convention abolished slavery across the colonies amid war and revolution. Napoleon later restored it where he could, revealing how quickly metropolitan commitments could yield to imperial profit.', significance: 'Emancipation was won through colonial revolt and remained vulnerable to counterrevolution.', focus: { lat: 19.45, lng: -72.68 }, source: { title: 'Encyclopaedia Britannica: Haitian Revolution', url: 'https://www.britannica.com/topic/Haitian-Revolution' } },
      { year: 1804, section: 'IV · Haitian independence', title: 'A formerly enslaved people defeats an empire', description: 'After defeating the expedition sent by Napoleon, Haitian leaders declared an independent state. The revolution destroyed legal slavery there and permanently transformed the Atlantic political imagination.', significance: 'Haiti made emancipation and anti-colonial sovereignty inseparable—and slaveholding states treated it as a threat.', eventId: 'haiti-independence' },
      { year: 1815, section: 'V · Revolutionary afterlives', title: 'Restoration cannot restore the old world', description: 'European monarchies defeated Napoleon and attempted to stabilize dynastic rule, but revolutionary law, nationalism, abolitionism, and independence movements continued. Haiti faced isolation and later a crushing indemnity to France.', significance: 'Outcomes depended on military power, recognition, finance, and whose freedom other states would tolerate.', entity: 'France', source: { title: 'Encyclopaedia Britannica: Congress of Vienna', url: 'https://www.britannica.com/event/Congress-of-Vienna' } },
    ],
  },
  {
    id: 'modern-world', title: 'The twentieth-century world remade', subtitle: 'World wars, decolonization, rival superpowers, technological ambition, and the Cold War’s end', category: 'Modern transformations', period: '1914–1991 CE', estimatedMinutes: 7, color: '#8b82d8',
    introduction: 'The twentieth century was not simply a contest between great powers. Industrial war mobilized whole societies and empires; anti-colonial movements created new states; revolutionary governments offered rival futures; and technology joined genuine achievement to systems of unprecedented violence.',
    conclusion: 'The Cold War ended without ending war, empire’s afterlives, nuclear danger, or struggles over political and economic order. The century shifted power toward the United States, Soviet Union, and revolutionary China while independent states and social movements reshaped international politics.',
    steps: [
      { year: 1914, section: 'I · Industrial world war', title: 'A regional assassination triggers a global conflict', description: 'The killing of Archduke Franz Ferdinand set off a diplomatic crisis among alliances shaped by militarism, nationalism, and imperial rivalry. European empires carried the war into colonies and oceans worldwide.', significance: 'The trigger was local; the machinery that made it a world war had been built over decades.', eventId: 'sarajevo' },
      { year: 1920, section: 'II · Empires fall, borders move', title: 'A new map emerges from war and revolution', description: 'The Russian, German, Austro-Hungarian, and Ottoman empires had collapsed or been transformed. New states claimed national self-determination while minorities, colonies, and disputed borders exposed its selective application.', significance: 'Peace settlements ended one war by creating arrangements that many people rejected.', entity: 'USSR' },
      { year: 1938, section: 'III · Dictatorship and expansion', title: 'The international order breaks down', description: 'Fascist Italy, Nazi Germany, and imperial Japan pursued expansion while democracies and the League of Nations failed to deter aggression. War in China and Spain already showed the widening crisis.', significance: 'The Second World War grew from interconnected wars and deliberate choices, not a sudden accident in 1939.', entity: 'Empire of Japan' },
      { year: 1945, section: 'IV · Ruin and reconstruction', title: 'War ends in devastation and nuclear violence', description: 'The defeat of the Axis ended genocide and occupation but left tens of millions dead, cities destroyed, and displaced people across continents. Atomic bombs destroyed Hiroshima and Nagasaki as the United Nations was founded.', significance: 'Institutions promising security arose from a war that also created the means to annihilate cities in moments.', entity: 'USSR' },
      { year: 1947, section: 'V · Decolonization', title: 'India and Pakistan become independent', description: 'British colonial rule ended through partition after decades of anti-colonial struggle. Independence arrived with mass displacement, communal killing, and competing claims over territory and national identity.', significance: 'The end of empire expanded sovereignty while colonial borders and hurried transfer produced lasting conflict.', eventId: 'india-independence', entity: 'India' },
      { year: 1949, section: 'VI · Revolutionary China', title: 'The People’s Republic is proclaimed', description: 'Communist forces won control of the mainland after civil war, Japanese invasion, and social upheaval. The new government pursued radical land, industrial, political, and social transformation.', significance: 'A populous former semi-colonial society became central to socialist and postcolonial world politics.', entity: 'China', eventId: 'prc-founded' },
      { year: 1957, section: 'V · Decolonization', title: 'Ghana links nationhood to pan-Africanism', description: 'Ghana became independent under Kwame Nkrumah and supported liberation movements elsewhere. Across Africa and Asia, new governments faced borders, economies, and institutions shaped by colonial rule.', significance: 'Independence changed international politics, but sovereignty did not eliminate unequal global power.', entity: 'Ghana', eventId: 'ghana-independence' },
      { year: 1969, section: 'VII · Technology and rivalry', title: 'People reach the Moon', description: 'Apollo 11 landed astronauts on the Moon after an enormous public program of science, engineering, manufacturing, and state spending. The achievement was also a demonstration within the Cold War.', significance: 'Technological ambition could unite expertise and public imagination while serving geopolitical competition.', entity: 'United States of America', eventId: 'apollo-11' },
      { year: 1989, section: 'VIII · Communist Europe changes', title: 'The Berlin Wall opens', description: 'Peaceful protest, Soviet reform, economic pressures, and political change across Eastern Europe weakened one-party governments. East Germany opened border crossings after a confused announcement and intense public pressure.', significance: 'The wall’s fall became a symbol, but citizens across the region had produced the change through sustained action.', eventId: 'berlin-wall' },
      { year: 1991, section: 'IX · The Soviet Union dissolves', title: 'A superpower becomes fifteen states', description: 'Economic crisis, political reform, nationalist movements, a failed coup, and declarations of sovereignty ended the Soviet Union. The transition brought new freedoms for some and severe insecurity for many.', significance: 'The Cold War order ended, but its institutions, weapons, borders, and memories remained active forces.', entity: 'USSR', eventId: 'ussr-dissolves' },
    ],
  },
  {
    id: 'indian-ocean', title: 'Worlds of the Indian Ocean', subtitle: 'Monsoon knowledge, port cities, religious exchange, merchant diasporas, and armed competition', category: 'Exchange & movement', period: '200 BCE–1600 CE', estimatedMinutes: 6, color: '#35a39a',
    introduction: 'For millennia the Indian Ocean connected African, Arabian, South Asian, Southeast Asian, and Chinese coasts. Seasonal winds made routes predictable, but sailors, brokers, rulers, craftspeople, and diasporic communities made the network work.',
    conclusion: 'Portuguese cannon changed the balance of maritime power without creating oceanic exchange or eliminating older participants. Swahili, Arab, Persian, Indian, Malay, and Chinese merchants and states adapted, competed, and continued to shape a commercial world no empire wholly controlled.',
    steps: [
      { year: -200, section: 'I · A sea timed by seasons', title: 'Monsoon winds connect regional routes', description: 'Sailors learned to use seasonally reversing winds to cross open water between East Africa, Arabia, India, and Southeast Asia. Voyages remained dangerous and depended on coastal knowledge and many intermediate ports.', significance: 'Shared environmental knowledge became essential infrastructure for reliable long-distance exchange.', routeId: 'indian-ocean' },
      { year: 800, section: 'II · Sacred and commercial landscapes', title: 'Borobudur rises in central Java', description: 'Builders created a monumental Buddhist sanctuary within a wealthy Javanese society connected to maritime Southeast Asia. Pilgrims moved through its terraces as a physical and symbolic journey.', significance: 'Religious ideas traveled through ocean networks and took powerful local forms.', pointId: 'borobudur' },
      { year: 1010, section: 'III · Courts look seaward', title: 'Chola power links land and ocean', description: 'Rajaraja I’s temple at Thanjavur expressed royal authority within an agrarian state whose merchants and later naval campaigns reached across the Bay of Bengal.', significance: 'Maritime influence depended on inland production, temples, ports, and negotiated commercial communities.', entity: 'Chola state', eventId: 'chola-temple' },
      { year: 1100, section: 'III · Courts look seaward', title: 'Gold links Great Zimbabwe to the coast', description: 'Great Zimbabwe grew as an inland political and commercial center connected through intermediary routes to Swahili ports. Imported objects testify to exchange, but local farming, cattle, craft, and authority sustained the state.', significance: 'Global connections strengthened an Indigenous state; they did not build it from outside.', entity: 'Great Zimbabwe', eventId: 'great-zimbabwe' },
      { year: 1200, section: 'IV · Port-city worlds', title: 'Kilwa prospers on the Swahili coast', description: 'Kilwa’s rulers and merchants benefited from trade in gold and other goods moving between the African interior and overseas markets. Coral-stone architecture expressed urban wealth and Islamic affiliation.', significance: 'African port cities were decision-making centers within the network, not passive endpoints.', pointId: 'kilwa' },
      { year: 1300, section: 'IV · Port-city worlds', title: 'Southeast Asian states mediate exchange', description: 'Srivijaya and its successors drew power from strategic straits, ports, tribute, and relationships with merchants. Political control shifted even while maritime routes remained busy.', significance: 'Control of chokepoints could be more valuable than governing a continuous land territory.', entity: 'Srivijaya Empire', routeId: 'indian-ocean' },
      { year: 1405, section: 'V · Imperial fleets', title: 'Zheng He enters a crowded ocean', description: 'Ming fleets traveled through Southeast Asia to India, Arabia, and East Africa. They sought recognition and displayed power within networks already organized by local rulers and merchants.', significance: 'The expeditions were exceptional in scale, not the beginning of Asian maritime exchange.', entity: 'Ming Chinese Empire', eventId: 'zheng-he' },
      { year: 1498, section: 'VI · Armed competition', title: 'Vasco da Gama reaches Calicut', description: 'The Portuguese expedition arrived with limited knowledge of local commerce and politics. Later fleets used naval violence, fortified ports, and passes to redirect trade and extract revenue.', significance: 'A new competitor sought monopoly in a system built on plural access and negotiated exchange.', entity: 'Portugal', eventId: 'da-gama' },
      { year: 1600, section: 'VI · Armed competition', title: 'Companies and states compete', description: 'Portuguese power now faced Ottoman, Safavid, Mughal, Southeast Asian, Dutch, English, and many local rivals. Chartered companies combined private capital with sovereign violence.', significance: 'The ocean remained multipolar even as European colonial institutions grew more powerful.', entity: 'Portugal', routeId: 'indian-ocean' },
    ],
  },
  {
    id: 'medieval-europe', title: 'Power and society in medieval Europe', subtitle: 'Post-Roman kingdoms, church and empire, conquest, law, cities, and Mediterranean connections', category: 'States & societies', period: '800–1453 CE', estimatedMinutes: 6, color: '#bd9450',
    introduction: '“Medieval Europe” covered a millennium of changing societies and should not be reduced to castles or a pause between Rome and modernity. This story follows political experiments and connections, while remembering that Europe was never isolated from Byzantine, Islamic, African, and Asian worlds.',
    conclusion: 'No medieval state became a modern nation by a straight path. Kings, nobles, clergy, towns, peasants, merchants, and communities negotiated overlapping rights and obligations, while war and faith connected Europe to a much wider world.',
    steps: [
      { year: 800, section: 'I · New claims to empire', title: 'Charlemagne is crowned in Rome', description: 'Pope Leo III crowned the Frankish ruler emperor after decades of conquest and religious reform. The act linked Frankish kingship to Roman and Christian claims while competing with the emperor in Constantinople.', significance: 'Several rulers could invoke Rome, revealing that imperial legitimacy was contested rather than inherited cleanly.', entity: 'Carolingian Empire', eventId: 'charlemagne' },
      { year: 843, section: 'II · Division and local power', title: 'The Carolingian realm is partitioned', description: 'Charlemagne’s grandsons divided the empire at Verdun after civil war. Successive partitions and external attacks strengthened regional rulers, monasteries, fortified centers, and local bonds of protection.', significance: 'Political fragmentation created new institutions; it was not simply the collapse of central government.', entity: 'Frankish Kingdom', eventId: 'verdun' },
      { year: 1000, section: 'III · A growing agrarian world', title: 'Population, cultivation, and lordship expand', description: 'Across many regions, communities cleared land, founded settlements, built churches, and intensified agriculture. Lords and religious institutions claimed rents and labor while peasants negotiated custom and resisted demands.', significance: 'The daily work of rural households supported courts, armies, towns, and monumental building.', entity: 'Holy Roman Empire' },
      { year: 1066, section: 'IV · Conquest and state-building', title: 'Norman victory remakes England’s elite', description: 'William of Normandy defeated Harold II at Hastings and redistributed land to a new ruling class. Castles, surveys, church reform, and continued resistance transformed government and society.', significance: 'A battle changed a kingdom because conquest was followed by systematic occupation and administration.', entity: 'England', eventId: 'hastings' },
      { year: 1200, section: 'V · Cities and Mediterranean exchange', title: 'Venice connects commercial worlds', description: 'Italian maritime cities linked European markets with Byzantine and Islamic ports. Merchants relied on credit, contracts, diasporic communities, shipbuilding, and political privileges as well as naval force.', significance: 'Medieval economic growth depended on cross-cultural exchange, not European isolation.', pointId: 'venice' },
      { year: 1215, section: 'VI · Power under law', title: 'Magna Carta binds a king', description: 'English barons forced King John to accept a charter addressing taxation, justice, inheritance, and elite rights. Most clauses served immediate interests, but later generations gave some principles a much wider constitutional meaning.', significance: 'Documents gain historical power through later interpretation as well as their original settlement.', entity: 'England', eventId: 'magna-carta' },
      { year: 1279, section: 'VII · Several Christian worlds', title: 'Latin and Byzantine spheres remain entangled', description: 'The restored Byzantine Empire governed from Constantinople after the trauma of the Fourth Crusade, while western kingdoms, Italian cities, and crusader states competed in the eastern Mediterranean.', significance: 'Religious identity did not prevent war among Christians or diplomacy across confessional lines.', entity: 'Byzantine Empire', pointId: 'constantinople-city' },
      { year: 1453, section: 'VIII · Transformation, not a curtain', title: 'Constantinople falls to the Ottomans', description: 'Mehmed II captured Constantinople and made it an Ottoman capital. Scholars often use the date to close the Middle Ages, but social and political change followed different chronologies across regions.', significance: 'Period labels help organize history; they do not make the world change everywhere at once.', entity: 'Ottoman Empire', eventId: 'constantinople' },
    ],
  },
]

export const getStory = (id: string | null) => historicalStories.find((story) => story.id === id)
